import type { Question } from '../../lib/types'
export const vpc_security_questions: Question[] = [
  { id: 'd1-vpc-001', domain: 1, topics: ['VPC', 'security groups', 'NACLs'], type: 'single', stem: 'A security group allows port 443 inbound. A NACL denies port 443 inbound. Which takes effect?', options: [{ id: 'A', text: 'Security group — security groups override NACLs for instance-level traffic' }, { id: 'B', text: 'NACL deny — NACLs are evaluated before security groups at the subnet boundary' }, { id: 'C', text: 'Both apply; the more restrictive rule wins per AWS policy' }, { id: 'D', text: 'Security group — stateful rules always override stateless NACL rules' }], correct: ['B'], explanation: 'NACLs are evaluated at the subnet boundary before traffic reaches the instance. A NACL deny blocks traffic before the security group is consulted.', distractors: { A: 'Security groups do not override NACLs — NACLs are the outer perimeter evaluated first.', C: 'There is no "more restrictive wins" merging — NACLs block at the subnet before security groups are reached.', D: 'Statefulness is a characteristic, not a priority override — NACL evaluation order is positional, not by type.' } },
  { id: 'd1-vpc-002', domain: 1, topics: ['VPC', 'security groups', 'stateful'], type: 'single', stem: 'A security group allows inbound port 80. An outbound rule for port 80 is NOT configured. Can the server respond?', options: [{ id: 'A', text: 'No — outbound rules must explicitly allow the response port' }, { id: 'B', text: 'Yes — security groups are stateful; response traffic is automatically allowed' }, { id: 'C', text: 'No — stateful means only that inbound rules track connection state, not outbound' }, { id: 'D', text: 'Yes — only if an outbound rule allows "All Traffic" to the client IP' }], correct: ['B'], explanation: 'Security groups are stateful. When an inbound connection is allowed, return traffic is automatically permitted regardless of outbound rules.', distractors: { A: 'Explicit outbound rules for return traffic are not needed — security groups track connection state.', C: 'Stateful means both directions of an established connection are tracked and allowed automatically.', D: '"All Traffic" outbound is not required — stateful tracking handles return traffic automatically.' } },
  { id: 'd1-vpc-003', domain: 1, topics: ['VPC', 'NACLs', 'stateless'], type: 'single', stem: 'A NACL allows inbound port 443. The client returns a response on ephemeral port 49152. NACL blocks it. Why?', options: [{ id: 'A', text: 'NACL automatically allows return traffic on all ports — this scenario is impossible' }, { id: 'B', text: 'NACLs are stateless; the outbound NACL must explicitly allow the ephemeral port range' }, { id: 'C', text: 'Port 49152 is a reserved port; NACLs always block reserved ports by default' }, { id: 'D', text: 'NACL rules apply only to inbound traffic — outbound is implicitly allowed' }], correct: ['B'], explanation: 'NACLs are stateless — they do not track connections. Return traffic on ephemeral ports must be explicitly allowed in outbound NACL rules (typically ports 1024–65535).', distractors: { A: 'NACLs do not automatically allow return traffic — that is security group behavior.', C: 'Ports above 1024 are ephemeral ports, not reserved — NACLs block them if no explicit rule allows them.', D: 'NACLs apply to both inbound and outbound traffic at the subnet level.' } },
  { id: 'd1-vpc-004', domain: 1, topics: ['VPC', 'Flow Logs', 'troubleshooting'], type: 'single', stem: 'Traffic to an EC2 instance is being dropped. How do you determine if security group or NACL is causing it?', options: [{ id: 'A', text: 'Check CloudTrail for security group and NACL modification events in the last hour' }, { id: 'B', text: 'Enable VPC Flow Logs; ACCEPT records mean SG/NACL allowed traffic; REJECT records show which layer dropped it' }, { id: 'C', text: 'Install a packet capture agent on the EC2 instance to see what arrives and what is dropped' }, { id: 'D', text: 'Use AWS Config to compare current security group rules with the baseline configuration' }], correct: ['B'], explanation: 'VPC Flow Logs record ACCEPT/REJECT decisions. NACL rejections appear at the subnet ENI; security group rejections appear at the instance ENI. Comparing both helps isolate the blocking layer.', distractors: { A: 'CloudTrail shows configuration changes — not real-time traffic allow/deny decisions.', C: 'Packet capture on the instance shows what arrives after the NACL — it cannot capture NACL-dropped traffic.', D: 'Config shows configuration drift — not whether traffic is currently being accepted or rejected.' } },
  { id: 'd1-vpc-005', domain: 1, topics: ['VPC', 'private subnet', 'internet access'], type: 'single', stem: 'EC2 in a private subnet needs to download software updates from the internet. Solution?', options: [{ id: 'A', text: 'Add an internet gateway route to the private subnet route table' }, { id: 'B', text: 'Deploy a NAT Gateway in a public subnet; add a route in the private subnet to the NAT Gateway' }, { id: 'C', text: 'Enable IPv6 on the private subnet — IPv6 enables direct internet access without NAT' }, { id: 'D', text: 'Use a VPC peering connection to a public subnet in a different VPC' }], correct: ['B'], explanation: 'NAT Gateway in a public subnet provides outbound-only internet access for private subnet instances. The private subnet route table sends 0.0.0.0/0 to the NAT GW, which has an IGW in its route table.', distractors: { A: 'Adding an IGW route to a private subnet makes it a public subnet and exposes instances to inbound internet traffic.', C: 'IPv6 with an IGW still requires the instance to be in a public subnet — use an Egress-Only IGW for private IPv6 egress.', D: 'VPC peering connects two VPCs — it does not provide internet access to instances.' } },
  { id: 'd1-vpc-006', domain: 1, topics: ['VPC', 'endpoints', 'Gateway'], type: 'single', stem: 'A private subnet EC2 instance must access S3 without going through the internet. Most cost-effective solution?', options: [{ id: 'A', text: 'Create an Interface VPC Endpoint for S3 — one per AZ for high availability' }, { id: 'B', text: 'Create an S3 Gateway VPC Endpoint — free, no data processing charges, added to route table' }, { id: 'C', text: 'Route traffic through NAT Gateway — no special endpoint configuration needed' }, { id: 'D', text: 'Enable S3 Transfer Acceleration — routes traffic over the AWS backbone instead of internet' }], correct: ['B'], explanation: 'S3 and DynamoDB Gateway Endpoints are free — no hourly charge, no data processing charge. They route S3 traffic within the AWS network without going through NAT Gateway.', distractors: { A: 'Interface Endpoints for S3 cost $0.01/hour per AZ — Gateway Endpoints are free and sufficient for most S3 use cases.', C: 'NAT Gateway costs $0.045/hour plus $0.045/GB processing — Gateway Endpoint eliminates this cost for S3.', D: 'Transfer Acceleration speeds up uploads — it does not route traffic over a private VPC connection.' } },
  { id: 'd1-vpc-007', domain: 1, topics: ['VPC', 'peering', 'limitations'], type: 'single', stem: 'VPC A is peered with VPC B, and VPC B is peered with VPC C. Can VPC A communicate with VPC C?', options: [{ id: 'A', text: 'Yes — transitive routing allows traffic to traverse multiple peering connections' }, { id: 'B', text: 'No — VPC peering does not support transitive routing; A cannot reach C through B' }, { id: 'C', text: 'Yes — if VPC B has routing tables configured to forward traffic between A and C' }, { id: 'D', text: 'Yes — but only if all three VPCs are in the same AWS account' }], correct: ['B'], explanation: 'VPC peering is non-transitive. Traffic between A and C requires a direct A↔C peering connection, or using Transit Gateway for hub-and-spoke connectivity.', distractors: { A: 'Transitive routing is explicitly NOT supported in VPC peering — it is the primary limitation.', C: 'Route tables cannot enable transitive peering — the networking model prohibits it by design.', D: 'Cross-account peering works — the non-transitive limitation applies regardless of account ownership.' } },
  { id: 'd1-vpc-008', domain: 1, topics: ['VPC', 'Transit Gateway', 'hub spoke'], type: 'single', stem: 'A company has 20 VPCs that all need to communicate with each other. What reduces the connection complexity vs mesh peering?', options: [{ id: 'A', text: 'Create a full mesh of VPC peering connections — 190 peering connections for 20 VPCs' }, { id: 'B', text: 'Use Transit Gateway as a hub — each VPC connects to TGW with a single attachment' }, { id: 'C', text: 'Combine all VPCs into one large VPC using VPC merging' }, { id: 'D', text: 'Use VPC sharing to give all accounts access to a single shared VPC' }], correct: ['B'], explanation: 'Transit Gateway acts as a hub. 20 VPCs need 20 TGW attachments vs 190 peering connections for full mesh. TGW also supports transitive routing that peering lacks.', distractors: { A: 'N*(N-1)/2 peering connections — 20 VPCs require 190 connections, which is operationally unmanageable.', C: 'VPCs cannot be merged — they are separate isolated networks with separate CIDR blocks.', D: 'VPC sharing shares subnets with other accounts — it does not connect separate VPCs for routing.' } },
  { id: 'd1-vpc-009', domain: 1, topics: ['VPC', 'security group', 'reference'], type: 'single', stem: 'An ALB security group and an EC2 security group are separate. How can EC2 allow traffic only from the ALB?', options: [{ id: 'A', text: 'Add the ALB\'s Elastic IP addresses to the EC2 security group inbound rules' }, { id: 'B', text: 'Reference the ALB security group ID as the source in the EC2 inbound rule' }, { id: 'C', text: 'Put the ALB and EC2 in the same security group so they can communicate freely' }, { id: 'D', text: 'Create a NACL allowing only the ALB subnet CIDR to reach the EC2 subnet' }], correct: ['B'], explanation: 'Security groups can reference other security group IDs as source/destination — any resource in the ALB SG is the source, eliminating the need to manage IP addresses.', distractors: { A: 'ALBs do not have static Elastic IPs — their IPs change dynamically and cannot be listed reliably.', C: 'Sharing one security group means all rules apply to both — loses fine-grained control between tiers.', D: 'NACL CIDR rules are coarser — they allow all traffic from the ALB subnet, not just ALB-origin traffic.' } },
  { id: 'd1-vpc-010', domain: 1, topics: ['VPC', 'PrivateLink', 'service endpoint'], type: 'single', stem: 'A SaaS provider wants to expose their service to customer VPCs without VPC peering or internet. Solution?', options: [{ id: 'A', text: 'Create a VPC peering connection from each customer VPC to the provider VPC' }, { id: 'B', text: 'AWS PrivateLink — provider creates a VPC endpoint service; customers create Interface Endpoints' }, { id: 'C', text: 'Use Transit Gateway with the SaaS provider attached as an external attachment' }, { id: 'D', text: 'Deploy the service publicly and use WAF to restrict access to customer IP ranges' }], correct: ['B'], explanation: 'PrivateLink allows services to be exposed privately to other VPCs. Provider creates an NLB-backed Endpoint Service. Customers create Interface Endpoints. Traffic stays on AWS backbone with no peering or internet.', distractors: { A: 'Peering exposes the entire VPC to the other VPC — PrivateLink exposes only the specific service.', C: 'TGW requires both parties to be in the same organization or use peering — PrivateLink is the purpose-built cross-account service exposure mechanism.', D: 'Public deployment exposes the service to the internet — PrivateLink keeps it entirely private.' } },
  { id: 'd1-vpc-011', domain: 1, topics: ['VPC', 'network ACL', 'rule numbering'], type: 'single', stem: 'A NACL has rule 100 allowing all traffic and rule 200 denying port 22. What happens to SSH traffic?', options: [{ id: 'A', text: 'Denied — rule 200 is a more specific rule and overrides the general rule 100' }, { id: 'B', text: 'Allowed — NACLs process rules in number order; rule 100 matches first and allows all traffic including SSH' }, { id: 'C', text: 'Denied — deny rules always override allow rules regardless of rule number' }, { id: 'D', text: 'Allowed — port 22 is considered a management port and is always allowed in NACL evaluation' }], correct: ['B'], explanation: 'NACLs process rules in ascending numeric order. The first matching rule applies. Rule 100 (allow all) matches SSH before rule 200 (deny 22) — SSH is allowed.', distractors: { A: 'NACLs do not apply specificity logic — rules are evaluated in numeric order and the first match wins.', C: 'Deny rules do not have categorical precedence in NACLs — only the first matching rule wins.', D: 'There is no special treatment for port 22 in NACLs — all ports follow the same evaluation order.' } },
  { id: 'd1-vpc-012', domain: 1, topics: ['VPC', 'default security group'], type: 'single', stem: 'What is the default behavior of an AWS default VPC security group?', options: [{ id: 'A', text: 'All inbound and outbound traffic is blocked by default' }, { id: 'B', text: 'All inbound traffic is allowed; outbound is blocked by default' }, { id: 'C', text: 'Inbound is denied except from the same security group; all outbound is allowed' }, { id: 'D', text: 'All traffic is allowed inbound and outbound by default' }], correct: ['C'], explanation: 'Default security group: inbound allows traffic only from instances also in the default SG (self-referencing rule); all outbound is allowed. New custom security groups block all inbound by default.', distractors: { A: 'The default SG allows inbound from its own members and all outbound — it is not fully blocked.', B: 'Inbound from everywhere is not the default — only inbound from the same security group is allowed.', D: 'All-traffic inbound is not the default SG behavior — only self-referencing inbound is allowed.' } },
  { id: 'd1-vpc-013', domain: 1, topics: ['VPC', 'CIDR', 'sizing'], type: 'single', stem: 'A VPC has CIDR 10.0.0.0/16. How many usable IP addresses does this provide?', options: [{ id: 'A', text: '65,534 — AWS reserves 5 IPs per subnet but not at the VPC level' }, { id: 'B', text: '65,536 total; first and last addresses are reserved; 65,534 usable across all subnets' }, { id: 'C', text: '256 — a /16 contains 256 /24 subnets each with 256 IPs' }, { id: 'D', text: '65,531 — AWS reserves 5 per VPC CIDR block from the total' }], correct: ['B'], explanation: '/16 = 2^16 = 65,536 total addresses. First (.0 network) and last (.255 broadcast) are unusable in IPv4; usable = 65,534. AWS reserves 5 IPs per SUBNET (not per VPC CIDR).', distractors: { A: 'AWS reserves 5 IPs per subnet, not from the VPC CIDR total — the 65,534 count is correct.', C: '256 is the count of /24 subnets in a /16 — not the IP count. The /16 itself has 65,536 IPs.', D: 'The 5-IP reservation applies per subnet — not a single 5-IP reduction from the VPC total.' } },
  { id: 'd1-vpc-014', domain: 1, topics: ['VPC', 'subnet', 'reserved IPs'], type: 'single', stem: 'A /24 subnet has 256 addresses. How many are usable by EC2 instances?', options: [{ id: 'A', text: '256 — AWS does not reserve any addresses in subnets' }, { id: 'B', text: '254 — first and last addresses are reserved for network and broadcast' }, { id: 'C', text: '251 — AWS reserves 5 addresses: network, broadcast, VPC router, DNS, and future use' }, { id: 'D', text: '250 — AWS reserves 6 addresses including the NAT Gateway address' }], correct: ['C'], explanation: 'AWS reserves 5 IPs per subnet: .0 (network), .1 (VPC router), .2 (DNS), .3 (future), .255 (broadcast) = 256 - 5 = 251 usable.', distractors: { A: 'AWS reserves exactly 5 addresses per subnet — not zero.', B: '254 is the standard IPv4 count — AWS reserves 5 (not 2), leaving 251.', D: 'Only 5 addresses are reserved — NAT Gateways are assigned from the available pool, not pre-reserved.' } },
  { id: 'd1-vpc-015', domain: 1, topics: ['VPC', 'DNS', 'private hosted zone'], type: 'single', stem: 'EC2 instances in a VPC need to resolve internal DNS names like database.internal. What enables this?', options: [{ id: 'A', text: 'Update each instance\'s /etc/hosts file with internal hostname mappings' }, { id: 'B', text: 'Create a Route 53 private hosted zone associated with the VPC; add DNS records there' }, { id: 'C', text: 'Enable VPC DNS hostnames setting — this automatically creates internal records' }, { id: 'D', text: 'Deploy a BIND DNS server on EC2 and configure it in the DHCP options set' }], correct: ['B'], explanation: 'Route 53 private hosted zones provide DNS resolution within a VPC. Associate the zone with the VPC; instances resolve records using the VPC\'s DNS resolver (Route 53 Resolver at x.x.x.2).', distractors: { A: 'Updating /etc/hosts per instance does not scale — private hosted zones provide centralized managed DNS.', C: 'DNS hostnames setting creates public/private EC2 hostnames — it does not create custom zone records.', D: 'A self-managed BIND server works but requires management overhead — Route 53 private hosted zones are the AWS-native solution.' } },
  { id: 'd1-vpc-016', domain: 1, topics: ['VPC', 'VPN', 'Site-to-Site'], type: 'single', stem: 'A company needs a secure encrypted connection between their on-premises network and AWS VPC. Options?', options: [{ id: 'A', text: 'VPC peering with the on-premises network configured as a remote VPC' }, { id: 'B', text: 'AWS Site-to-Site VPN — IPsec tunnels over the internet between on-premises and a Virtual Private Gateway' }, { id: 'C', text: 'AWS Direct Connect — a private fiber connection from on-premises to AWS' }, { id: 'D', text: 'Both B and C are valid options; VPN is internet-based, Direct Connect is dedicated private fiber' }], correct: ['D'], explanation: 'Both are valid for on-premises to VPC connectivity: VPN uses IPsec over internet (quick, cheap, limited bandwidth); Direct Connect uses dedicated private fiber (consistent latency, higher throughput, higher cost).', distractors: { A: 'VPC peering is for VPC-to-VPC connections — it does not connect on-premises networks.', B: 'VPN alone is correct but incomplete — Direct Connect is also a valid and commonly used option.', C: 'Direct Connect alone is correct but incomplete — VPN is also a valid option for many use cases.' } },
  { id: 'd1-vpc-017', domain: 1, topics: ['VPC', 'reachability', 'analyzer'], type: 'single', stem: 'A developer cannot connect to an EC2 instance but is not sure if the issue is SG, NACL, routing, or IGW. Quick diagnostic?', options: [{ id: 'A', text: 'Check VPC Flow Logs for REJECT records on the instance ENI' }, { id: 'B', text: 'VPC Reachability Analyzer — traces a logical path between two endpoints and identifies the specific blocking component' }, { id: 'C', text: 'Run traceroute from the developer\'s machine to identify where packets stop' }, { id: 'D', text: 'Check CloudTrail for any recent security group or NACL modification events' }], correct: ['B'], explanation: 'VPC Reachability Analyzer performs a logical hop-by-hop analysis without sending traffic. It identifies exactly which security group, NACL, route table, or gateway is blocking connectivity.', distractors: { A: 'Flow Logs show whether traffic was accepted or rejected but do not identify which specific component caused the rejection.', C: 'Traceroute requires live traffic — it cannot diagnose logical configuration issues without actually reaching the network.', D: 'CloudTrail shows config changes — it does not analyze current connectivity between two endpoints.' } },
  { id: 'd1-vpc-018', domain: 1, topics: ['VPC', 'egress only IGW', 'IPv6'], type: 'single', stem: 'IPv6-enabled EC2 instances in a private subnet need outbound internet access. What provides this?', options: [{ id: 'A', text: 'NAT Gateway — supports both IPv4 and IPv6 outbound traffic' }, { id: 'B', text: 'Egress-Only Internet Gateway — provides outbound IPv6 internet access, blocks inbound' }, { id: 'C', text: 'Internet Gateway — add a route for ::/0 to the private subnet route table' }, { id: 'D', text: 'IPv6 does not require a gateway — instances route natively to the internet' }], correct: ['B'], explanation: 'Egress-Only Internet Gateway is the IPv6 equivalent of NAT Gateway — allows outbound IPv6 traffic to the internet while blocking unsolicited inbound connections.', distractors: { A: 'NAT Gateway only supports IPv4 — it does not handle IPv6 traffic.', C: 'Adding an IGW route to a private subnet makes it public — the Egress-Only IGW maintains private subnet isolation.', D: 'IPv6 addresses are globally routable but still require gateway routing — no automatic internet routing without a gateway.' } },
  { id: 'd1-vpc-019', domain: 1, topics: ['VPC', 'interface endpoint', 'security'], type: 'single', stem: 'An Interface VPC Endpoint for SSM must only be accessible from within the VPC. What enforces this?', options: [{ id: 'A', text: 'Attach the endpoint to the private subnet only — public subnets cannot see interface endpoints' }, { id: 'B', text: 'Endpoint policy — restrict access to specific VPC IDs, principals, or CIDR ranges' }, { id: 'C', text: 'VPC endpoint security groups — allow inbound traffic only from VPC CIDR' }, { id: 'D', text: 'Both B and C — endpoint policies and security groups both control Interface Endpoint access' }], correct: ['D'], explanation: 'Interface Endpoints have two access controls: (1) Security Group — controls network-level access; (2) Endpoint Policy — controls IAM-level permissions for which principals can use the endpoint. Both should be configured.', distractors: { A: 'Interface endpoints are in specific subnets but can be routed to from any subnet — subnet placement alone is not access control.', B: 'Endpoint policy is one layer — security groups are the other. Both are needed for complete control.', C: 'Security group is one layer — endpoint policy is the other. Both are needed for complete control.' } },
  { id: 'd1-vpc-020', domain: 1, topics: ['VPC', 'shared VPC', 'RAM'], type: 'single', stem: 'A central team manages shared subnets used by multiple AWS accounts. What enables this without VPC peering?', options: [{ id: 'A', text: 'Copy the VPC configuration to each account — manual process for synchronization' }, { id: 'B', text: 'AWS Resource Access Manager (RAM) — share VPC subnets with other accounts in the org' }, { id: 'C', text: 'Transit Gateway — connects each account\'s VPC to a central VPC' }, { id: 'D', text: 'AWS Organizations SCPs — allow member accounts to create resources in another account\'s VPC' }], correct: ['B'], explanation: 'VPC sharing via RAM: owner account shares specific subnets with participant accounts. Participants launch resources into shared subnets — one VPC, multiple account owners. No peering needed.', distractors: { A: 'Copying configuration to each account creates separate VPCs, not a shared one — defeats the purpose.', C: 'TGW connects VPCs for routing — it does not let accounts share the same VPC subnets.', D: 'SCPs control permissions — they cannot grant cross-account VPC resource creation access.' } },
  { id: 'd1-vpc-021', domain: 1, topics: ['VPC', 'DHCP options', 'DNS'], type: 'single', stem: 'EC2 instances in a VPC should use a custom DNS server at 10.0.0.2. How is this configured?', options: [{ id: 'A', text: 'Set the DNS server in each EC2 instance\'s /etc/resolv.conf manually' }, { id: 'B', text: 'Create a custom DHCP Options Set with the custom DNS server and associate it with the VPC' }, { id: 'C', text: 'Update the VPC DNS settings in the VPC console to point to the custom server' }, { id: 'D', text: 'Create a Route 53 inbound resolver endpoint that forwards queries to the custom server' }], correct: ['B'], explanation: 'DHCP Options Sets configure DNS servers, NTP servers, and domain names delivered via DHCP to VPC instances. Associate a custom set with the VPC to override the default AWS-provided DNS.', distractors: { A: 'Manual per-instance configuration does not scale — DHCP Options Sets apply to all instances in the VPC.', C: 'There is no direct "DNS settings" in the VPC console separate from DHCP Options Sets.', D: 'Route 53 Resolver endpoints are for hybrid DNS (on-premises ↔ VPC) — DHCP Options Sets configure the default resolver for instances.' } },
  { id: 'd1-vpc-022', domain: 1, topics: ['VPC', 'security group', 'rules limit'], type: 'single', stem: 'A security group needs 150 inbound rules for different CIDR blocks. Default limit is 60 rules per security group. Solution?', options: [{ id: 'A', text: 'Create a second security group with the remaining rules — EC2 supports multiple security groups per instance' }, { id: 'B', text: 'Request a service quota increase via Service Quotas console — max 1,000 rules per security group' }, { id: 'C', text: 'Use a NACL instead — NACLs support up to 20 inbound rules by default' }, { id: 'D', text: 'Both A and B are valid approaches — multiple security groups and quota increases are both supported' }], correct: ['D'], explanation: 'Two valid approaches: (1) Attach multiple security groups to the instance (up to 5 per ENI by default); (2) Request a quota increase (up to 1,000 rules per SG). Or use managed prefix lists to consolidate CIDRs.', distractors: { A: 'Multiple SGs is valid but incomplete — quota increases are also supported.', B: 'Quota increase is valid but incomplete — multiple SGs are also supported.', C: 'NACLs have lower default limits (20 rules) — using a NACL is not a solution for security group rule limits.' } },
  { id: 'd1-vpc-023', domain: 1, topics: ['VPC', 'managed prefix list'], type: 'single', stem: 'Thirty security groups each need a rule for the same 10 corporate CIDR blocks. Efficient management?', options: [{ id: 'A', text: 'Add all 10 CIDRs to each security group rule individually — 300 total rule entries' }, { id: 'B', text: 'Create a managed prefix list with the 10 CIDRs; reference the prefix list in all 30 security groups' }, { id: 'C', text: 'Use one shared security group for all resources to reduce duplicate rules' }, { id: 'D', text: 'Store CIDRs in Parameter Store and script nightly sync to all security groups' }], correct: ['B'], explanation: 'Managed Prefix Lists: define a group of CIDRs once, reference the prefix list ID in security group rules. Update the prefix list — all 30 security groups update automatically.', distractors: { A: '300 rule entries require manual updates across 30 groups when CIDRs change — prefix lists centralize this.', C: 'Sharing one SG for all resources loses isolation — prefix lists maintain separate SGs with shared CIDR management.', D: 'Scripted sync is fragile and adds operational overhead — managed prefix lists are the native solution.' } },
  { id: 'd1-vpc-024', domain: 1, topics: ['VPC', 'Direct Connect', 'private VIF'], type: 'single', stem: 'Direct Connect provides a private connection to VPC resources. What virtual interface is used for this?', options: [{ id: 'A', text: 'Public VIF — connects to public AWS service endpoints like S3 from on-premises' }, { id: 'B', text: 'Private VIF — connects to VPC private IP addresses via a Virtual Private Gateway' }, { id: 'C', text: 'Transit VIF — connects to Transit Gateway for multiple VPC access from a single DX' }, { id: 'D', text: 'Both B and C — Private VIF for single VPC, Transit VIF for multiple VPCs via TGW' }], correct: ['D'], explanation: 'For VPC connectivity: Private VIF attaches to a Virtual Private Gateway (single VPC). Transit VIF attaches to Transit Gateway (multiple VPCs, single DX connection). Public VIF reaches public AWS endpoints.', distractors: { A: 'Public VIF is for AWS public services (S3, EC2 APIs) — not for private VPC IP addresses.', B: 'Private VIF is correct for single VPC — but Transit VIF is also valid for multi-VPC access.', C: 'Transit VIF is correct for multi-VPC — but Private VIF is also valid for single VPC access.' } },
  { id: 'd1-vpc-025', domain: 1, topics: ['VPC', 'Network Firewall', 'deployment'], type: 'single', stem: 'AWS Network Firewall is deployed in a dedicated firewall subnet. How does traffic from application subnets reach it?', options: [{ id: 'A', text: 'Network Firewall automatically intercepts all VPC traffic — no routing changes needed' }, { id: 'B', text: 'Route application subnet traffic to a VPC endpoint for the firewall; IGW ingress routing to the firewall endpoint for internet traffic' }, { id: 'C', text: 'Security group rules force traffic through the firewall using the firewall instance ID as a target' }, { id: 'D', text: 'Network Firewall uses VPC mirroring to inspect traffic without routing changes' }], correct: ['B'], explanation: 'Network Firewall deployment requires policy-based routing: route tables direct traffic to the firewall endpoint IDs. Ingress routing via the IGW routes inbound internet traffic through the firewall before reaching application subnets.', distractors: { A: 'Network Firewall is not transparent — explicit route table changes are required to route traffic through it.', C: 'Security groups control port/IP access — they cannot force traffic inspection through a firewall.', D: 'VPC Traffic Mirroring creates copies for inspection — Network Firewall requires inline routing, not mirroring.' } },
  { id: 'd1-vpc-026', domain: 1, topics: ['VPC', 'bastion host', 'SSH'], type: 'single', stem: 'Administrators need SSH access to private EC2 instances. Most secure managed alternative to a bastion host?', options: [{ id: 'A', text: 'Open port 22 on the private instances to a corporate IP range in the security group' }, { id: 'B', text: 'AWS Systems Manager Session Manager — browser/CLI-based shell access without SSH or inbound ports' }, { id: 'C', text: 'Deploy a bastion host in a public subnet with restricted SSH access from corporate IPs' }, { id: 'D', text: 'VPN connection from corporate to VPC; then SSH to private IPs over VPN' }], correct: ['B'], explanation: 'SSM Session Manager provides audited shell access to EC2 instances — no SSH keys, no inbound port 22 needed. Sessions are logged to CloudWatch/S3. Eliminates bastion host attack surface.', distractors: { A: 'Opening port 22 to any IP range exposes SSH to potential brute force — no audit trail without additional tooling.', C: 'Bastion host is a valid approach but adds a management burden and attack surface vs Session Manager.', D: 'VPN + SSH is valid but requires VPN infrastructure and SSH key management — Session Manager eliminates both.' } },
  { id: 'd1-vpc-027', domain: 1, topics: ['VPC', 'flow logs', 'format'], type: 'single', stem: 'VPC Flow Logs are enabled. What traffic information is captured?', options: [{ id: 'A', text: 'Full packet payload including HTTP headers and request body content' }, { id: 'B', text: 'Source IP, destination IP, ports, protocol, bytes, action (ACCEPT/REJECT), and log status' }, { id: 'C', text: 'Only rejected traffic — accepted traffic is not logged by default' }, { id: 'D', text: 'DNS query names and responses for all traffic passing through the VPC' }], correct: ['B'], explanation: 'VPC Flow Logs capture network metadata per flow: source/dest IP, source/dest port, protocol, packet count, byte count, timestamp, ACCEPT/REJECT. No packet payload content is captured.', distractors: { A: 'Flow logs capture metadata only — no packet payload, HTTP headers, or request body is included.', C: 'Flow logs capture both ACCEPT and REJECT records — you can filter in CloudWatch or Athena.', D: 'DNS query logging is a separate Route 53 Resolver feature — not part of VPC Flow Logs.' } },
  { id: 'd1-vpc-028', domain: 1, topics: ['VPC', 'Transit Gateway', 'route tables'], type: 'single', stem: 'A Transit Gateway has prod VPCs and dev VPCs. How do you prevent prod-to-dev direct communication?', options: [{ id: 'A', text: 'Create security group rules denying cross-environment traffic in all VPCs' }, { id: 'B', text: 'Create separate TGW route tables for prod and dev; associate VPCs to their environment route table; no route to cross-environment' }, { id: 'C', text: 'Use separate Transit Gateways for prod and dev environments' }, { id: 'D', text: 'Apply NACLs on all prod subnets to deny all dev CIDR ranges' }], correct: ['B'], explanation: 'TGW route table segmentation: create separate route tables per environment, associate VPCs to their environment table. Prod VPCs only see prod routes; dev VPCs only see dev routes — network-level isolation.', distractors: { A: 'Security groups must be maintained per-instance — TGW route tables enforce isolation at the network level more effectively.', C: 'Separate TGW per environment works but is more expensive and adds management overhead vs route table segmentation.', D: 'NACLs per subnet work but require maintaining CIDR lists in every subnet across all prod VPCs.' } },
  { id: 'd1-vpc-029', domain: 1, topics: ['VPC', 'DNS resolution', 'enableDnsSupport'], type: 'single', stem: 'The VPC has enableDnsSupport=false. What is the impact on EC2 instances?', options: [{ id: 'A', text: 'EC2 instances cannot connect to the internet — DNS is required for internet routing' }, { id: 'B', text: 'The Route 53 Resolver (x.x.x.2 DNS server) is disabled — instances cannot resolve any DNS unless a custom DNS is configured' }, { id: 'C', text: 'Only public DNS hostnames are disabled — private hostname resolution still works' }, { id: 'D', text: 'enableDnsSupport only affects IPv6 DNS — IPv4 DNS resolution is unaffected' }], correct: ['B'], explanation: 'enableDnsSupport controls whether the Route 53 Resolver is enabled at the VPC level. With it disabled, the .2 DNS resolver is unavailable. Instances need an alternative DNS server configured via DHCP Options.', distractors: { A: 'Internet connectivity and DNS are separate — DNS failure blocks name resolution but IP-addressed connections still work.', C: 'enableDnsHostnames controls public DNS hostnames; enableDnsSupport controls the DNS resolver availability.', D: 'enableDnsSupport applies to all DNS resolution in the VPC — not IPv6-specific.' } },
  { id: 'd1-vpc-030', domain: 1, topics: ['VPC', 'Route 53 Resolver', 'hybrid DNS'], type: 'single', stem: 'On-premises servers need to resolve Route 53 private hosted zone records. Solution?', options: [{ id: 'A', text: 'Make the private hosted zone public so on-premises DNS can query it' }, { id: 'B', text: 'Create a Route 53 Inbound Resolver Endpoint in the VPC; configure on-premises DNS to forward to the endpoint IPs' }, { id: 'C', text: 'Create a Route 53 Outbound Resolver Endpoint; configure forwarding rules to the on-premises DNS' }, { id: 'D', text: 'Enable Route 53 resolver sharing — private zones are automatically visible to on-premises over Direct Connect' }], correct: ['B'], explanation: 'Inbound Resolver Endpoint: elastic network interfaces in the VPC that accept DNS queries from on-premises. On-premises DNS servers forward private zone queries to the endpoint IPs. Requires Direct Connect or VPN.', distractors: { A: 'Making zones public removes private isolation — on-premises DNS would then expose internal records publicly.', C: 'Outbound endpoints forward queries FROM the VPC TO on-premises DNS — the reverse direction of what is needed.', D: 'Private zones are not automatically visible to on-premises — Inbound Resolver Endpoints are required.' } },
  { id: 'd1-vpc-031', domain: 1, topics: ['VPC', 'security groups', 'port range'], type: 'single', stem: 'A security group rule needs to allow all TCP traffic. Which port range entry is correct?', options: [{ id: 'A', text: 'Port 0 to 65536 — covers all TCP ports including port 0' }, { id: 'B', text: 'Port 1 to 65535 — the usable TCP port range' }, { id: 'C', text: 'Port 0 to 65535 — the full TCP port range including both 0 and 65535' }, { id: 'D', text: 'Use the "All TCP" shortcut which automatically applies 0-65535 in the console' }], correct: ['C'], explanation: 'TCP port range is 0–65535. Port 0 is technically reserved but AWS security groups accept 0-65535 as the "all TCP" range. The console "All TCP" option applies this automatically.', distractors: { A: 'Port 65536 does not exist — valid TCP port range is 0-65535.', B: 'Port 1-65535 is nearly complete but excludes port 0 — use 0-65535 for all TCP.', D: 'The "All TCP" shortcut is correct behavior — answer C describes what it sets numerically.' } },
  { id: 'd1-vpc-032', domain: 1, topics: ['VPC', 'IPAM', 'IP management'], type: 'single', stem: 'A company needs to manage non-overlapping IP address space across 50 VPCs and multiple accounts. Solution?', options: [{ id: 'A', text: 'Maintain a spreadsheet tracking CIDR allocation per VPC across all accounts' }, { id: 'B', text: 'AWS VPC IP Address Manager (IPAM) — centrally allocate, track, and audit IP space across accounts and regions' }, { id: 'C', text: 'Use RFC 1918 address space in each account independently and manage overlap with TGW routing' }, { id: 'D', text: 'Assign all VPCs the same /24 CIDR — TGW handles routing conflicts automatically' }], correct: ['B'], explanation: 'VPC IPAM is a managed service for IP address planning — allocate CIDR pools per region/account, enforce non-overlap, track utilization, and audit all allocations from a central view.', distractors: { A: 'Spreadsheet management is error-prone and does not scale — IPAM automates tracking and conflict detection.', C: 'Overlapping CIDR blocks cause routing issues in TGW — IPAM prevents overlap by enforcing allocations.', D: 'Overlapping /24 CIDRs in all VPCs prevent routing — TGW cannot resolve IP conflicts, only route differences.' } },
  { id: 'd1-vpc-033', domain: 1, topics: ['VPC', 'Gateway Load Balancer', 'inline inspection'], type: 'single', stem: 'All traffic entering or leaving a VPC must be inspected by a third-party firewall appliance. Which deployment pattern?', options: [{ id: 'A', text: 'Place the firewall behind an ALB and route traffic to it via health checks' }, { id: 'B', text: 'AWS Gateway Load Balancer — routes traffic to firewall appliances transparently; maintains source IP; scales automatically' }, { id: 'C', text: 'VPC Traffic Mirroring — copies all traffic to the firewall for inspection' }, { id: 'D', text: 'Deploy the firewall as an EC2 NAT instance in each VPC and route 0.0.0.0/0 to it' }], correct: ['B'], explanation: 'GWLB distributes traffic to a fleet of firewall appliances using GENEVE protocol — transparent, source-IP preserving, auto-scaling. The standard pattern for third-party inline inspection in AWS.', distractors: { A: 'ALB is for application load balancing — it cannot route all traffic types inline for firewall inspection.', C: 'Traffic Mirroring creates copies for out-of-band analysis — the original traffic is not inspected inline.', D: 'EC2 NAT instances are manual, not auto-scaling, and create a single point of failure in each VPC.' } },
  { id: 'd1-vpc-034', domain: 1, topics: ['VPC', 'lattice', 'service mesh'], type: 'single', stem: 'Multiple services across multiple VPCs and accounts need service-to-service communication with centralized policies. What is the purpose-built solution?', options: [{ id: 'A', text: 'VPC Peering with service mesh software installed on EC2 instances' }, { id: 'B', text: 'AWS VPC Lattice — application networking for service-to-service communication with central policy management' }, { id: 'C', text: 'Transit Gateway with route tables segmented per service group' }, { id: 'D', text: 'AWS PrivateLink with separate endpoint services per service pair' }], correct: ['B'], explanation: 'VPC Lattice is a managed application networking service for service-to-service communication. Define services, associate them in a service network, and apply auth policies and access controls centrally.', distractors: { A: 'Self-managed service mesh on EC2 requires operational overhead — VPC Lattice is the managed AWS-native alternative.', C: 'TGW provides network routing — it does not provide service-level policies or auth between services.', D: 'PrivateLink is for point-to-point service exposure — VPC Lattice provides multi-service network with centralized policy management.' } },
  { id: 'd1-vpc-035', domain: 1, topics: ['VPC', 'traffic mirroring'], type: 'single', stem: 'A security team needs to capture network traffic from EC2 instances for threat analysis without impacting production. Solution?', options: [{ id: 'A', text: 'Enable VPC Flow Logs with full packet capture mode for complete traffic recording' }, { id: 'B', text: 'VPC Traffic Mirroring — mirrors traffic from ENIs to a target (NLB or ENI); out-of-band inspection without performance impact' }, { id: 'C', text: 'Install tcpdump on each EC2 instance to capture packets and forward to a SIEM' }, { id: 'D', text: 'Enable Network Firewall deep packet inspection mode and export to S3' }], correct: ['B'], explanation: 'VPC Traffic Mirroring duplicates packets from ENIs to an out-of-band destination — zero impact on production traffic. Captured traffic can be analyzed by IDS/SIEM tools.', distractors: { A: 'VPC Flow Logs capture metadata (IP, port, bytes) only — not full packet payloads.', C: 'tcpdump on production instances adds CPU/memory overhead and requires per-instance installation.', D: 'Network Firewall DPI is inline — it inspects and blocks but is not designed for passive mirroring to SIEM.' } },
  { id: 'd1-vpc-036', domain: 1, topics: ['VPC', 'NAT gateway', 'HA'], type: 'single', stem: 'A single NAT Gateway in AZ-1 goes down. Instances in AZ-2 lose internet access. How to fix for future AZ failures?', options: [{ id: 'A', text: 'Create a second NAT Gateway in AZ-1 as a standby for failover' }, { id: 'B', text: 'Deploy one NAT Gateway per AZ; update each AZ\'s private route table to use its local NAT GW' }, { id: 'C', text: 'Use NAT instances instead — they support cross-AZ failover automatically' }, { id: 'D', text: 'Set the single NAT Gateway to multi-AZ mode in the NAT Gateway settings' }], correct: ['B'], explanation: 'Best practice: one NAT Gateway per AZ, each private subnet routes to its local NAT GW. If one AZ fails, the other AZs\' instances continue to work through their own NAT GWs.', distractors: { A: 'A second NAT GW in the same AZ provides no protection if that AZ fails — AZ diversification is needed.', C: 'NAT Instances do not support automatic cross-AZ failover — they require manual or custom failover scripts.', D: 'NAT Gateways do not have a multi-AZ mode — they are per-AZ resources by design.' } },
  { id: 'd1-vpc-037', domain: 1, topics: ['VPC', 'endpoint policy', 'S3'], type: 'single', stem: 'A Gateway VPC Endpoint for S3 must only allow access to a specific S3 bucket. What enforces this?', options: [{ id: 'A', text: 'Security group on the VPC endpoint restricting access to a specific bucket ARN' }, { id: 'B', text: 'VPC endpoint policy — allows or denies API calls on specific resources (bucket ARNs)' }, { id: 'C', text: 'S3 bucket policy condition aws:SourceVpce restricting access to the endpoint' }, { id: 'D', text: 'Both B and C — endpoint policy restricts from the endpoint side; bucket policy restricts from the S3 side' }], correct: ['D'], explanation: 'Both controls are complementary: Endpoint Policy (on the endpoint) restricts what the endpoint can reach. S3 Bucket Policy (on S3) restricts which endpoints can access it. Use both for defense in depth.', distractors: { A: 'Gateway Endpoints do not have security groups — only Interface Endpoints have security groups.', B: 'Endpoint policy alone is one layer — S3 bucket policy adds the second layer of defense.', C: 'S3 bucket policy alone is one layer — endpoint policy adds the first layer of control.' } },
  { id: 'd1-vpc-038', domain: 1, topics: ['VPC', 'inter-region peering'], type: 'single', stem: 'Two VPCs in different AWS regions need to communicate. Options?', options: [{ id: 'A', text: 'VPC peering is limited to same-region — inter-region VPCs cannot communicate privately' }, { id: 'B', text: 'Inter-region VPC peering — traffic uses AWS backbone; OR Transit Gateway inter-region peering' }, { id: 'C', text: 'Site-to-Site VPN between the two VPCs using Virtual Private Gateways' }, { id: 'D', text: 'CloudFront connects the two VPCs for cross-region resource access' }], correct: ['B'], explanation: 'Inter-region VPC peering is supported — traffic stays on the AWS global backbone. Alternatively, TGW inter-region peering provides centralized routing for multiple VPC cross-region connectivity.', distractors: { A: 'Inter-region VPC peering has been supported since 2017 — it is not limited to same-region.', C: 'Site-to-Site VPN is for on-premises connectivity — not for VPC-to-VPC in different regions.', D: 'CloudFront is a CDN — it does not provide VPC-to-VPC networking.' } },
  { id: 'd1-vpc-039', domain: 1, topics: ['VPC', 'customer gateway', 'VPN'], type: 'single', stem: 'In an AWS Site-to-Site VPN setup, what is the Customer Gateway?', options: [{ id: 'A', text: 'The AWS-managed Virtual Private Gateway attached to the VPC' }, { id: 'B', text: 'An AWS resource representing the on-premises VPN device — stores its public IP and BGP ASN' }, { id: 'C', text: 'The VPN tunnel endpoint on the AWS side of the connection' }, { id: 'D', text: 'A gateway appliance deployed in a public subnet within the customer\'s VPC' }], correct: ['B'], explanation: 'Customer Gateway is an AWS resource (logical) representing the on-premises VPN device. You specify the device\'s public IP and optionally its BGP ASN. The VGW or TGW is the AWS side of the tunnel.', distractors: { A: 'The Virtual Private Gateway (VGW) is the AWS-managed side — the Customer Gateway represents the on-premises side.', C: 'The VPN tunnel endpoint on the AWS side is the Virtual Private Gateway or TGW — not the Customer Gateway.', D: 'Customer Gateway is a logical AWS resource representing on-premises equipment — not a subnet-deployed appliance in the VPC.' } },
  { id: 'd1-vpc-040', domain: 1, topics: ['VPC', 'accelerated VPN'], type: 'single', stem: 'Site-to-Site VPN has high latency due to internet routing. How can AWS reduce this latency?', options: [{ id: 'A', text: 'Enable VPN High Availability — two tunnels improve latency through redundancy' }, { id: 'B', text: 'Accelerated Site-to-Site VPN — uses Global Accelerator to route traffic over AWS backbone from on-premises' }, { id: 'C', text: 'Use Express Routing on the VPN — a premium tier with SLA-backed latency guarantees' }, { id: 'D', text: 'Deploy the VPN Customer Gateway closer to an AWS region to reduce internet hops' }], correct: ['B'], explanation: 'Accelerated VPN uses AWS Global Accelerator — traffic from on-premises enters the nearest AWS PoP and travels the AWS backbone to the VPC. Reduces internet latency for international offices significantly.', distractors: { A: 'HA VPN uses two tunnels for redundancy — it does not improve latency for either tunnel.', C: 'There is no "Express Routing" tier for AWS VPN — it does not exist as a product.', D: 'Customer Gateway location is constrained to where on-premises hardware exists — it cannot always be moved.' } },
  { id: 'd1-vpc-041', domain: 1, topics: ['VPC', 'security group', 'outbound'], type: 'single', stem: 'A new custom security group is created. What are the default inbound and outbound rules?', options: [{ id: 'A', text: 'All traffic allowed both inbound and outbound by default' }, { id: 'B', text: 'No inbound rules (all inbound blocked); one outbound rule allowing all traffic to 0.0.0.0/0' }, { id: 'C', text: 'All inbound blocked; all outbound blocked — must explicitly configure all rules' }, { id: 'D', text: 'Inbound allows port 80 and 443; outbound allows all traffic by default' }], correct: ['B'], explanation: 'New custom security groups: no inbound rules (default deny all inbound); one outbound rule allowing all traffic outbound (default allow all outbound). Add inbound rules as needed.', distractors: { A: 'New custom SGs do not allow all inbound — they block all inbound by default.', C: 'Outbound traffic is allowed by default — only inbound is blocked.', D: 'No port-specific defaults exist for custom SGs — inbound is blocked completely by default.' } },
  { id: 'd1-vpc-042', domain: 1, topics: ['VPC', 'subnet', 'public vs private'], type: 'single', stem: 'What makes a subnet "public" in AWS?', options: [{ id: 'A', text: 'The subnet is named "public" in the AWS console' }, { id: 'B', text: 'The subnet has a route to an Internet Gateway (0.0.0.0/0 → IGW) in its route table' }, { id: 'C', text: 'Instances in the subnet are assigned public IP addresses automatically' }, { id: 'D', text: 'The subnet has a NACL that allows inbound traffic from 0.0.0.0/0' }], correct: ['B'], explanation: 'A public subnet is defined by its route table having a route to an Internet Gateway. Name and IP assignment settings are independent — the route table entry is the definition.', distractors: { A: 'Subnet names are labels only — they have no effect on routing or internet accessibility.', C: 'Auto-assign public IPs is a subnet setting — but without an IGW route, those IPs are unreachable from the internet.', D: 'NACL rules allow or block traffic — they do not make a subnet public; the route to IGW is the definition.' } },
  { id: 'd1-vpc-043', domain: 1, topics: ['VPC', 'route table', 'most specific'], type: 'single', stem: 'A route table has two routes: 10.0.0.0/8 → TGW and 10.1.0.0/16 → VPC Peering. Traffic to 10.1.2.3 — which route is used?', options: [{ id: 'A', text: '10.0.0.0/8 → TGW — longer routes take precedence only for internet routing' }, { id: 'B', text: '10.1.0.0/16 → VPC Peering — most specific route (longest prefix match) always wins' }, { id: 'C', text: 'Traffic is split equally between both routes using ECMP' }, { id: 'D', text: 'Both routes match; the lower route table rule number wins' }], correct: ['B'], explanation: 'Longest prefix match: /16 is more specific than /8. Traffic to 10.1.2.3 uses the 10.1.0.0/16 route to VPC Peering — always.', distractors: { A: 'Longest prefix match applies to all routing in AWS — not just internet routing.', C: 'ECMP (Equal Cost Multi-Path) applies when routes have the same prefix length — not with different prefix lengths.', D: 'AWS route tables use longest prefix match — there is no rule number priority for conflicting routes.' } },
  { id: 'd1-vpc-044', domain: 1, topics: ['VPC', 'inter-VPC', 'overlapping CIDR'], type: 'single', stem: 'Two VPCs have overlapping CIDRs (both 10.0.0.0/16). Can they be peered?', options: [{ id: 'A', text: 'Yes — VPC peering handles overlapping CIDRs with NAT-based address translation' }, { id: 'B', text: 'No — VPC peering requires non-overlapping CIDRs; overlapping blocks cannot be peered' }, { id: 'C', text: 'Yes — but only if they are in different AWS regions' }, { id: 'D', text: 'Yes — use Transit Gateway with route summarization to resolve the overlap' }], correct: ['B'], explanation: 'VPC peering requires non-overlapping CIDR blocks. If CIDRs overlap, the routing table cannot distinguish which VPC a given IP belongs to — peering is rejected at creation.', distractors: { A: 'VPC peering has no built-in NAT — it requires non-overlapping CIDRs for routing to work.', C: 'Cross-region peering has the same non-overlapping CIDR requirement as same-region peering.', D: 'Transit Gateway also requires non-overlapping CIDRs to create unambiguous routes between VPCs.' } },
  { id: 'd1-vpc-045', domain: 1, topics: ['VPC', 'security', 'defense in depth'], type: 'multi', stem: 'Which TWO are true about using both security groups and NACLs together?', options: [{ id: 'A', text: 'Security groups are stateful and operate at the instance/ENI level' }, { id: 'B', text: 'NACLs are stateless and operate at the subnet boundary level' }, { id: 'C', text: 'NACLs can replace security groups entirely for equivalent protection' }, { id: 'D', text: 'Security groups can deny specific IPs; NACLs cannot' }], correct: ['A', 'B'], explanation: 'Defense in depth: NACLs are stateless subnet-level filters (first line); security groups are stateful instance-level filters (second line). Using both adds layered protection.', distractors: { C: 'NACLs are stateless and require explicit return traffic rules — security groups provide easier stateful protection that NACLs cannot replicate.', D: 'Security groups have no explicit deny — they only allow (default deny). NACLs CAN explicitly deny specific IPs.' } },
]
